import{c as p,o as e,b as r}from"./index-D22dK0d7.js";const s={class:"markdown-body"},m={__name:"Часто задаваемые вопросы",setup(n,{expose:o}){return o({frontmatter:{}}),(h,t)=>(e(),p("div",s,[...t[0]||(t[0]=[r("<h2>Можно ли вам позвонить?</h2><p>Созвон не предусмотрен — процесс подключения полностью автоматический. После регистрации вы сразу получаете доступ к личному кабинету и настраиваете интеграцию самостоятельно за 5–10 минут: всё интуитивно понятно, с подсказками внутри сервиса. Если возникнут вопросы — пишите на почту или в чат, отвечаем быстро и всегда с подробными скриншотами. Такой формат удобнее: у вас остаётся история переписки с решением, к которой можно вернуться в любой момент.</p><h2>Сколько длится тестовый период?</h2><p><strong>14 дней.</strong> Доступен полный функционал без ограничений.</p><h2>Можно ли переписываться с телефона?</h2><p>Да. Сообщения синхронизируются: ответил с телефона — запись появится в CRM, ответил из CRM — клиент увидит сообщение в мессенджере. История не теряется.</p><h2>Сколько номеров можно подключить?</h2><p>Любое количество. Ограничений нет. Подключайте один номер или сто — платите только за те, которые реально используете.</p><h2>Нужно ли держать телефон включённым постоянно?</h2><p>Нет. Телефон может быть выключен — сообщения всё равно придут в CRM.</p><h2>Есть ли ограничения по количеству сообщений?</h2><p>Нет. Тарифы ограничены только количеством подключённых номеров, а не количеством сообщений.</p>",12)])]))}};export{m as default};
